INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cjp-cteni-s-porozumenim_0','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Jak se nazývá rodina včel?',ARRAY['trubci','včelstvo','roj','úl']::TEXT[],1,'Odpověď plyne přímo z textu: včelstvo.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_1','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kolik členů má včelstvo v létě?',ARRAY['asi sto','až šest tisíc','až šedesát tisíc','přesně jeden']::TEXT[],2,'Odpověď plyne přímo z textu: až šedesát tisíc.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_2','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kdo sbírá nektar a pyl?',ARRAY['larvy','královna','dělnice','trubci']::TEXT[],2,'Odpověď plyne přímo z textu: dělnice.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_3','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Co platí o trubcích?',ARRAY['hlídají úl','sbírají pyl','kladou vajíčka','na práci se nepodílejí']::TEXT[],3,'Odpověď plyne přímo z textu: na práci se nepodílejí.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_4','Text: „Včely žijí v rodinách, které nazýváme včelstva. V létě má včelstvo až šedesát tisíc členů. Většinu z nich tvoří dělnice, které sbírají nektar a pyl, starají se o larvy a hlídají úl. Samečci, trubci, se na práci nepodílejí. Vajíčka klade jediná včelí královna.“ Otázka: Kdo ve včelstvu klade vajíčka?',ARRAY['trubci','larvy','všechny dělnice','jediná královna']::TEXT[],3,'Odpověď plyne přímo z textu: jediná královna.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_5','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Kdo zahájil stavbu Karlova mostu?',ARRAY['Karel Čapek','Rudolf II.','Karel IV.','Přemysl Otakar II.']::TEXT[],2,'Odpověď plyne přímo z textu: Karel IV..',2,ARRAY[]::TEXT[],NULL,5,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_6','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: V kterém roce byla zahájena stavba mostu?',ARRAY['1357','1457','1257','1757']::TEXT[],0,'Odpověď plyne přímo z textu: 1357.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_7','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Na kolika pilířích stojí Karlův most?',ARRAY['na šestnácti','na dvanácti','na šesti','na šedesáti']::TEXT[],0,'Odpověď plyne přímo z textu: na šestnácti.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_8','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Proč po mostě nejezdí auta?',ARRAY['je příliš nový','je určen pouze pro chodce','je zavřený','je právě opravován']::TEXT[],1,'Odpověď plyne přímo z textu: je určen pouze pro chodce.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_9','Text: „Karlův most je nejstarší dochovaný most přes Vltavu v Praze. Jeho stavbu zahájil roku 1357 Karel IV. Je dlouhý přibližně 516 metrů a stojí na šestnácti pilířích. Dnes po něm nejezdí auta, protože je určen pouze pro chodce.“ Otázka: Jak dlouhý je Karlův most podle textu?',ARRAY['přibližně 516 metrů','přibližně 51 metrů','přibližně 5 kilometrů','přibližně 160 metrů']::TEXT[],0,'Odpověď plyne přímo z textu: přibližně 516 metrů.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_10','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Proč Tomáš vstal brzy?',ARRAY['chtěl stihnout první autobus','bál se mlhy','měl hlad','byla mu zima']::TEXT[],0,'Odpověď plyne přímo z textu: chtěl stihnout první autobus.',4,ARRAY[]::TEXT[],NULL,10,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_11','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Jaké bylo ráno podle textu?',ARRAY['svítilo slunce','mrzlo a byla mlha','pršelo','foukal vítr']::TEXT[],1,'Odpověď plyne přímo z textu: mrzlo a byla mlha.',4,ARRAY[]::TEXT[],NULL,11,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_12','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Co Tomáš snědl?',ARRAY['nic','chleba s máslem','kaši','rohlík s džemem']::TEXT[],1,'Odpověď plyne přímo z textu: chleba s máslem.',5,ARRAY[]::TEXT[],NULL,12,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_13','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Kdo stál na zastávce?',ARRAY['řidič autobusu','Tomášův bratr','stará paní s košíkem','malá holčička']::TEXT[],2,'Odpověď plyne přímo z textu: stará paní s košíkem.',5,ARRAY[]::TEXT[],NULL,13,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_14','Text: „Tomáš vstal brzy ráno, protože chtěl stihnout první autobus. Venku mrzlo a z okna byla vidět jen bílá mlha. Rychle snědl chleba s máslem, vzal batoh a vyběhl ze dveří. Na zastávce už stála stará paní s košíkem a usmála se na něj.“ Otázka: Kdo je hlavní postavou textu?',ARRAY['řidič','Tomáš','maminka','stará paní']::TEXT[],1,'Odpověď plyne přímo z textu: Tomáš.',5,ARRAY[]::TEXT[],NULL,14,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_15','Text: „Eva má ráda zvířata. Doma má kočku Míšu a rybičky v akvárku. Každé ráno jim dává jídlo a večer s nimi mluví.“ Otázka: Jaká zvířata má Eva doma?',ARRAY['králíka a morčátko','koně a slepici','psa a papouška','kočku a rybičky']::TEXT[],3,'V textu: kočka Míša a rybičky.',1,ARRAY[]::TEXT[],NULL,15,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_16','Text: „Eva má ráda zvířata. Doma má kočku Míšu a rybičky v akvárku. Každé ráno jim dává jídlo a večer s nimi mluví.“ Otázka: Jak se jmenuje Evina kočka?',ARRAY['Míša','Lucka','Bětka','Anička']::TEXT[],0,'Kočka se jmenuje Míša.',1,ARRAY[]::TEXT[],NULL,16,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_17','Text: „Eva má ráda zvířata. Doma má kočku Míšu a rybičky v akvárku. Každé ráno jim dává jídlo a večer s nimi mluví.“ Otázka: Co Eva dělá každé ráno?',ARRAY['dává zvířatům jídlo','hraje si','jde do školy','čte knihy']::TEXT[],0,'Každé ráno jim dává jídlo.',1,ARRAY[]::TEXT[],NULL,17,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_18','Text: „Eva má ráda zvířata. Doma má kočku Míšu a rybičky v akvárku. Každé ráno jim dává jídlo a večer s nimi mluví.“ Otázka: Kdy Eva mluví se zvířaty?',ARRAY['večer','ráno','v poledne','v noci']::TEXT[],0,'Večer s nimi mluví.',1,ARRAY[]::TEXT[],NULL,18,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_19','Text: „Eva má ráda zvířata. Doma má kočku Míšu a rybičky v akvárku. Každé ráno jim dává jídlo a večer s nimi mluví.“ Otázka: Kde mají rybičky své akvárko?',ARRAY['doma','v jezeře','v řece','na zahradě']::TEXT[],0,'Rybičky jsou doma v akvárku.',1,ARRAY[]::TEXT[],NULL,19,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_20','Text: „Pražský hrad je jeden z největších hradních komplexů na světě. Leží na vrchu nad Vltavou. Stavba začala v 9. století a dnes je sídlem prezidenta republiky.“ Otázka: Kde leží Pražský hrad?',ARRAY['na vrchu nad Vltavou','u moře','na Moravě','v lese']::TEXT[],0,'Leží na vrchu nad Vltavou.',2,ARRAY[]::TEXT[],NULL,20,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_21','Text: „Pražský hrad je jeden z největších hradních komplexů na světě. Leží na vrchu nad Vltavou. Stavba začala v 9. století a dnes je sídlem prezidenta republiky.“ Otázka: Kdy začala stavba hradu?',ARRAY['ve 12. století','v 9. století','v 15. století','v 19. století']::TEXT[],1,'Stavba začala v 9. století.',2,ARRAY[]::TEXT[],NULL,21,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_22','Text: „Pražský hrad je jeden z největších hradních komplexů na světě. Leží na vrchu nad Vltavou. Stavba začala v 9. století a dnes je sídlem prezidenta republiky.“ Otázka: Co je dnes sídlem Pražského hradu?',ARRAY['muzeum','nemocnice','sídlo prezidenta republiky','škola']::TEXT[],2,'Je sídlem prezidenta.',2,ARRAY[]::TEXT[],NULL,22,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_23','Text: „Pražský hrad je jeden z největších hradních komplexů na světě. Leží na vrchu nad Vltavou. Stavba začala v 9. století a dnes je sídlem prezidenta republiky.“ Otázka: Co se o hradu v textu říká?',ARRAY['je to zřícenina','je to jeden z největších hradních komplexů','je to nejmenší hrad','leží u moře']::TEXT[],1,'Je to jeden z největších komplexů.',2,ARRAY[]::TEXT[],NULL,23,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_24','Text: „Pražský hrad je jeden z největších hradních komplexů na světě. Leží na vrchu nad Vltavou. Stavba začala v 9. století a dnes je sídlem prezidenta republiky.“ Otázka: Která řeka protéká pod hradem?',ARRAY['Morava','Ohře','Vltava','Labe']::TEXT[],2,'Vltava.',2,ARRAY[]::TEXT[],NULL,24,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_25','Text: „Rodina Novákových vyjela v sobotu na výlet do Krkonoš. Cesta vlakem trvala dvě hodiny. Na Sněžce foukal silný vítr, a tak si vzali teplé bundy. Večer se vrátili unavení, ale spokojení.“ Otázka: Kam rodina jela?',ARRAY['k moři','do Alp','do Krkonoš','do Tater']::TEXT[],2,'Vyjeli do Krkonoš.',3,ARRAY[]::TEXT[],NULL,25,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_26','Text: „Rodina Novákových vyjela v sobotu na výlet do Krkonoš. Cesta vlakem trvala dvě hodiny. Na Sněžce foukal silný vítr, a tak si vzali teplé bundy. Večer se vrátili unavení, ale spokojení.“ Otázka: Jak dlouho trvala cesta vlakem?',ARRAY['tři hodiny','dvě hodiny','pět hodin','hodinu']::TEXT[],1,'Trvala dvě hodiny.',3,ARRAY[]::TEXT[],NULL,26,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_27','Text: „Rodina Novákových vyjela v sobotu na výlet do Krkonoš. Cesta vlakem trvala dvě hodiny. Na Sněžce foukal silný vítr, a tak si vzali teplé bundy. Večer se vrátili unavení, ale spokojení.“ Otázka: Proč si vzali teplé bundy?',ARRAY['pršelo','foukal silný vítr','bylo horko','sněžilo']::TEXT[],1,'Na Sněžce foukal vítr.',3,ARRAY[]::TEXT[],NULL,27,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_28','Text: „Rodina Novákových vyjela v sobotu na výlet do Krkonoš. Cesta vlakem trvala dvě hodiny. Na Sněžce foukal silný vítr, a tak si vzali teplé bundy. Večer se vrátili unavení, ale spokojení.“ Otázka: Jak se rodina vrátila?',ARRAY['nešťastná','rozzlobená','unavená, ale spokojená','nasazená']::TEXT[],2,'Vrátili se unavení, ale spokojení.',3,ARRAY[]::TEXT[],NULL,28,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_29','Text: „Rodina Novákových vyjela v sobotu na výlet do Krkonoš. Cesta vlakem trvala dvě hodiny. Na Sněžce foukal silný vítr, a tak si vzali teplé bundy. Večer se vrátili unavení, ale spokojení.“ Otázka: Ve který den vyjeli?',ARRAY['v neděli','v pondělí','v pátek','v sobotu']::TEXT[],3,'Vyjeli v sobotu.',3,ARRAY[]::TEXT[],NULL,29,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_30','Text: „Hodně lidí si myslí, že jablka jsou jen sladká. Ve skutečnosti existuje mnoho odrůd, které chutnají kyselé, sladkokyselé nebo dokonce hořce. Odrůdy se liší také barvou slupky a velikostí plodů.“ Otázka: Co si mnoho lidí myslí o jablkách?',ARRAY['že jsou zelená','že nejsou zdravá','že jsou jen sladká','že jsou kyselá']::TEXT[],2,'Myslí si, že jsou jen sladká.',4,ARRAY[]::TEXT[],NULL,30,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_31','Text: „Hodně lidí si myslí, že jablka jsou jen sladká. Ve skutečnosti existuje mnoho odrůd, které chutnají kyselé, sladkokyselé nebo dokonce hořce. Odrůdy se liší také barvou slupky a velikostí plodů.“ Otázka: Čím se odrůdy liší podle textu?',ARRAY['délkou stromu','barvou slupky a velikostí plodů','místem původu','tvarem listů']::TEXT[],1,'Barvou slupky a velikostí plodů.',4,ARRAY[]::TEXT[],NULL,31,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_32','Text: „Hodně lidí si myslí, že jablka jsou jen sladká. Ve skutečnosti existuje mnoho odrůd, které chutnají kyselé, sladkokyselé nebo dokonce hořce. Odrůdy se liší také barvou slupky a velikostí plodů.“ Otázka: Jakou chuť mohou mít některé odrůdy?',ARRAY['pouze kořeněnou','pouze slanou','kyselou, sladkokyselou nebo hořkou','pouze sladkou']::TEXT[],2,'Kyselou, sladkokyselou nebo hořkou.',4,ARRAY[]::TEXT[],NULL,32,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_33','Text: „Hodně lidí si myslí, že jablka jsou jen sladká. Ve skutečnosti existuje mnoho odrůd, které chutnají kyselé, sladkokyselé nebo dokonce hořce. Odrůdy se liší také barvou slupky a velikostí plodů.“ Otázka: Co je hlavní myšlenkou textu?',ARRAY['jablka jsou nezdravá','existuje mnoho odrůd jablek s různou chutí','jablka se nesmí jíst','jablka rostou jen v zahradách']::TEXT[],1,'Odrůd je mnoho.',4,ARRAY[]::TEXT[],NULL,33,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_34','Text: „Hodně lidí si myslí, že jablka jsou jen sladká. Ve skutečnosti existuje mnoho odrůd, které chutnají kyselé, sladkokyselé nebo dokonce hořce. Odrůdy se liší také barvou slupky a velikostí plodů.“ Otázka: Jaký je hlavní problém tvrzení v textu?',ARRAY['je vtipné','je zastaralé','je zjednodušené','je pravdivé']::TEXT[],2,'Tvrzení o sladkosti je zjednodušené.',4,ARRAY[]::TEXT[],NULL,34,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_35','Text: „Babička Marie pekla každou sobotu buchty. Vnuci jí pomáhali s těstem a později je zdobili ovocem. Nejradši měli buchty s povidly, které babička připravovala podle staré rodinné receptury.“ Otázka: Co babička Marie pekla každou sobotu?',ARRAY['buchty','rohlíky','chleba','koláče']::TEXT[],0,'Pekla buchty.',5,ARRAY[]::TEXT[],NULL,35,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_36','Text: „Babička Marie pekla každou sobotu buchty. Vnuci jí pomáhali s těstem a později je zdobili ovocem. Nejradši měli buchty s povidly, které babička připravovala podle staré rodinné receptury.“ Otázka: Kdo babičce pomáhal s těstem?',ARRAY['sousedé','vnuci','dědeček','sestra']::TEXT[],1,'Pomáhali jí vnuci.',5,ARRAY[]::TEXT[],NULL,36,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_37','Text: „Babička Marie pekla každou sobotu buchty. Vnuci jí pomáhali s těstem a později je zdobili ovocem. Nejradši měli buchty s povidly, které babička připravovala podle staré rodinné receptury.“ Otázka: Čím buchty zdobili?',ARRAY['cukrem','čokoládou','ovocem','smetanou']::TEXT[],2,'Zdobili je ovocem.',5,ARRAY[]::TEXT[],NULL,37,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_38','Text: „Babička Marie pekla každou sobotu buchty. Vnuci jí pomáhali s těstem a později je zdobili ovocem. Nejradši měli buchty s povidly, které babička připravovala podle staré rodinné receptury.“ Otázka: Jaké buchty měli vnuci nejraději?',ARRAY['s povidly','se zelím','s tvarohem','s mákem']::TEXT[],0,'Nejradši měli s povidly.',5,ARRAY[]::TEXT[],NULL,38,'c_cjp-cteni-s-porozumenim',NULL,NOW()),
('q_cjp-cteni-s-porozumenim_39','Text: „Babička Marie pekla každou sobotu buchty. Vnuci jí pomáhali s těstem a později je zdobili ovocem. Nejradši měli buchty s povidly, které babička připravovala podle staré rodinné receptury.“ Otázka: Podle čeho babička připravovala povidla?',ARRAY['podle receptu od sousedky','podle receptu z televize','podle receptu z knihy','podle staré rodinné receptury']::TEXT[],3,'Podle staré rodinné receptury.',5,ARRAY[]::TEXT[],NULL,39,'c_cjp-cteni-s-porozumenim',NULL,NOW())
